// Test normalizeId
console.log('normalizeId examples:');
console.log('  normalizeId(\"c-007 \"):', normalizeId('c-007 '));
console.log('  normalizeId(\" C-001\"):', normalizeId(' C-001'));
console.log('  normalizeId(\" c-003  \"):', normalizeId(' c-003  '));
console.log();

// Test getCustomer with non-normalized IDs
console.log('getCustomer with various ID formats:');
const r1 = getCustomer('c-001');
console.log('  getCustomer(\"c-001\"):', r1.ok ? r1.value.name : 'NOT FOUND');

const r2 = getCustomer(' C-007 ');
console.log('  getCustomer(\" C-007 \"):', r2.ok ? r2.value.name : 'NOT FOUND');

const r3 = getCustomer('  c-003  ');
console.log('  getCustomer(\"  c-003  \"):', r3.ok ? r3.value.name : 'NOT FOUND');
console.log();

// Test createInvoice with non-normalized IDs
console.log('createInvoice stores normalized customer ID:');
const invoice1 = createInvoice({
  customerId: 'c-001',
  issueDate: '2026-10-07',
  lines: [{ sku: 'DES-HOUR', qty: 1 }],
});
console.log('  Input: \"c-001\", Stored:', invoice1.value.customerId);

const invoice2 = createInvoice({
  customerId: ' C-002 ',
  issueDate: '2026-10-07',
  lines: [{ sku: 'DES-HOUR', qty: 1 }],
});
console.log('  Input: \" C-002 \", Stored:', invoice2.value.customerId);
